using System;
using System.Collections.Concurrent;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

sealed class Node
{
    public Node Left;
    public Node Right;
    public Node(Node l, Node r) { Left = l; Right = r; }
}

static class Program
{
    static Node Bottom(int depth)
    {
        if (depth > 0)
            return new Node(Bottom(depth - 1), Bottom(depth - 1));
        return new Node(null, null);
    }

    static int Check(Node n)
    {
        int c = 1;
        while (n.Left != null)
        {
            c += Check(n.Left) + 1;
            n = n.Right;
        }
        return c;
    }

    static void Main(string[] args)
    {
        int n = args.Length > 0 ? int.Parse(args[0]) : 6;
        const int minDepth = 4;
        int maxDepth = Math.Max(minDepth + 2, n);
        int stretchDepth = maxDepth + 1;

        var sb = new StringBuilder();

        {
            Node stretch = Bottom(stretchDepth);
            sb.Append("stretch tree of depth ").Append(stretchDepth)
              .Append("\t check: ").Append(Check(stretch)).Append('\n');
            stretch = null;
        }

        Node longLived = Bottom(maxDepth);

        int groups = (maxDepth - minDepth) / 2 + 1;
        string[] results = new string[groups];
        int procs = Environment.ProcessorCount;

        for (int g = 0; g < groups; g++)
        {
            int depth = minDepth + 2 * g;
            int iterations = 1 << (maxDepth - depth + minDepth);
            long total = 0;

            int chunk = Math.Max(1, iterations / (procs * 16));
            var partitioner = Partitioner.Create(0, iterations, chunk);

            Parallel.ForEach(partitioner,
                () => 0L,
                (range, state, local) =>
                {
                    long sum = local;
                    for (int i = range.Item1; i < range.Item2; i++)
                        sum += Check(Bottom(depth));
                    return sum;
                },
                local => Interlocked.Add(ref total, local));

            results[g] = iterations + "\t trees of depth " + depth + "\t check: " + total;
        }

        for (int g = 0; g < groups; g++)
            sb.Append(results[g]).Append('\n');

        sb.Append("long lived tree of depth ").Append(maxDepth)
          .Append("\t check: ").Append(Check(longLived)).Append('\n');

        var stdout = Console.OpenStandardOutput();
        byte[] bytes = Encoding.ASCII.GetBytes(sb.ToString());
        stdout.Write(bytes, 0, bytes.Length);
        stdout.Flush();
    }
}
