using System;
using System.Threading;

class Program
{
    static int n;
    static int[] Fact;
    static int chunkSz, nChunks;
    static int[] maxFlips, chkSums;
    static int taskId = -1;

    static void FirstPermutation(int[] p, int[] pp, int[] count, int idx)
    {
        for (int i = 0; i < n; ++i) p[i] = i;
        for (int i = n - 1; i > 0; --i)
        {
            int d = idx / Fact[i];
            count[i] = d;
            idx = idx % Fact[i];
            Array.Copy(p, 0, pp, 0, i + 1);
            for (int j = 0; j <= i; ++j)
                p[j] = j + d <= i ? pp[j + d] : pp[j + d - i - 1];
        }
    }

    static void NextPermutation(int[] p, int[] count)
    {
        int first = p[1];
        p[1] = p[0];
        p[0] = first;
        int i = 1;
        while (++count[i] > i)
        {
            count[i++] = 0;
            int next = p[0] = p[1];
            for (int j = 1; j < i; ++j) p[j] = p[j + 1];
            p[i] = first;
            first = next;
        }
    }

    static int CountFlips(int[] p, int[] pp)
    {
        int flips = 1;
        int first = p[0];
        if (p[first] != 0)
        {
            Array.Copy(p, 0, pp, 0, n);
            do
            {
                ++flips;
                for (int lo = 1, hi = first - 1; lo < hi; ++lo, --hi)
                {
                    int t = pp[lo]; pp[lo] = pp[hi]; pp[hi] = t;
                }
                int t2 = pp[first];
                pp[first] = first;
                first = t2;
            } while (pp[first] != 0);
        }
        return flips;
    }

    static void Run()
    {
        int[] p = new int[n];
        int[] pp = new int[n];
        int[] count = new int[n];
        int task;
        while ((task = Interlocked.Increment(ref taskId)) < nChunks)
        {
            int idxMin = task * chunkSz;
            int idxMax = Math.Min(Fact[n], idxMin + chunkSz);
            FirstPermutation(p, pp, count, idxMin);
            int maxf = 0, chk = 0;
            for (int i = idxMin; ;)
            {
                if (p[0] != 0)
                {
                    int f = CountFlips(p, pp);
                    if (f > maxf) maxf = f;
                    chk += (i & 1) == 0 ? f : -f;
                }
                if (++i == idxMax) break;
                NextPermutation(p, count);
            }
            maxFlips[task] = maxf;
            chkSums[task] = chk;
        }
    }

    static void Main(string[] args)
    {
        n = int.Parse(args[0]);
        Fact = new int[n + 1];
        Fact[0] = 1;
        for (int i = 1; i <= n; ++i) Fact[i] = Fact[i - 1] * i;

        int nThreads = Math.Max(1, Environment.ProcessorCount);
        int target = 150;
        chunkSz = (Fact[n] + target - 1) / target;
        if (chunkSz < 1) chunkSz = 1;
        nChunks = (Fact[n] + chunkSz - 1) / chunkSz;
        maxFlips = new int[nChunks];
        chkSums = new int[nChunks];

        Thread[] threads = new Thread[nThreads];
        for (int i = 0; i < nThreads; ++i)
        {
            threads[i] = new Thread(Run);
            threads[i].Start();
        }
        for (int i = 0; i < nThreads; ++i) threads[i].Join();

        int res = 0, chkTot = 0;
        for (int i = 0; i < nChunks; ++i)
        {
            if (maxFlips[i] > res) res = maxFlips[i];
            chkTot += chkSums[i];
        }
        Console.WriteLine(chkTot);
        Console.WriteLine("Pfannkuchen(" + n + ") = " + res);
    }
}
