    static void RunRows(int threads, Action<int, int> body)
    {
        if (threads == 1) { body(0, n); return; }
        var tasks = new Task[threads];
        int chunk = (n + threads - 1) / threads;
        for (int k = 0; k < threads; k++)
        {
